-- MODO CARREIRA ONLINE — RESET DEFINITIVO + CONFIGURAÇÃO
-- Este arquivo apaga APENAS as tabelas do MCO e recria tudo do zero.
-- Execute este arquivo inteiro UMA VEZ no SQL Editor do Supabase.

DROP TABLE IF EXISTS public.jogadores, public.transferencias, public.noticias, public.comunidade, public.comentarios, public.agenda, public.links, public.perfis, public.clubes CASCADE;

-- Modo Carreira Online — estrutura inicial do Supabase
-- Execute este arquivo UMA VEZ no SQL Editor do Supabase.

create table if not exists public.clubes (id bigint generated by default as identity primary key, nome text not null unique, presidente text not null, tecnico text not null, saldo numeric(15,2) not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.jogadores (id bigint generated by default as identity primary key, clube_id bigint not null references public.clubes(id) on delete cascade, nome text not null, nacionalidade text not null default 'BR', posicao text not null default 'CA', salario numeric(15,2) not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.transferencias (id bigint generated by default as identity primary key, jogador text not null, tipo text not null, clube_origem text, clube_destino text, valor text, created_at timestamptz not null default now());
create table if not exists public.noticias (id bigint generated by default as identity primary key, titulo text not null, texto text default '', imagem text, usuario text not null default 'Participante', data_publicacao timestamptz not null default now());
create table if not exists public.comunidade (id bigint generated by default as identity primary key, usuario text not null default 'Participante', texto text default '', imagem text, data_publicacao timestamptz not null default now());
create table if not exists public.comentarios (id bigint generated by default as identity primary key, tipo text not null check (tipo in ('news','com')), post_id bigint not null, usuario text not null default 'Participante', texto text not null, created_at timestamptz not null default now());
create table if not exists public.agenda (id bigint generated by default as identity primary key, dia text not null unique, atividade text not null);
create table if not exists public.links (id bigint generated by default as identity primary key, nome text not null unique, url text not null);
create table if not exists public.perfis (id bigint generated by default as identity primary key, usuario text not null unique, bio text not null default '', updated_at timestamptz not null default now());

-- Dados iniciais dos 20 clubes e jogadores existentes no HTML


-- VERIFICAÇÃO FINAL
SELECT
  (SELECT count(*) FROM public.clubes) AS clubes,
  (SELECT count(*) FROM public.jogadores) AS jogadores,
  (SELECT count(*) FROM public.transferencias) AS transferencias,
  (SELECT count(*) FROM public.noticias) AS noticias,
  (SELECT count(*) FROM public.comunidade) AS comunidade,
  (SELECT count(*) FROM public.agenda) AS agenda,
  (SELECT count(*) FROM public.links) AS links,
  (SELECT count(*) FROM public.perfis) AS perfis;

SELECT c.nome, count(j.id) AS jogadores
FROM public.clubes c
LEFT JOIN public.jogadores j ON j.clube_id = c.id
GROUP BY c.id, c.nome
ORDER BY c.id;
